body{background:radial-gradient(60% 50% at 10% 0%,rgba(124,58,237,.22),transparent 60%),radial-gradient(50% 50% at 95% 100%,rgba(6,182,212,.14),transparent 60%),#070b18;color:#ffffff}
.shop-page{color:#ffffff}.shop-page .sec-title{padding:38px 20px 30px;margin:0 auto 22px;border-radius:24px;background:linear-gradient(135deg,#a78bfa22,#22d3ee22);border:1px solid rgba(255,255,255,.18);text-align:center}
.shop-page .sec-title h1{color:#ffffff}.shop-page .sec-title p{color:#cbd5e1}.shop-page .sec-title .kicker{color:#a78bfa;font-weight:800}
