.shop-page .grid .card{background:linear-gradient(145deg,rgba(255,255,255,.09),rgba(255,255,255,.03))!important;border:1px solid rgba(255,255,255,.18)!important;border-radius:20px!important;box-shadow:0 18px 44px rgba(0,0,0,.45),inset 0 1px 0 rgba(255,255,255,.14)!important;color:#ffffff!important;overflow:hidden;backdrop-filter:blur(14px);}.shop-page .grid .card .thumb{background:transparent}.shop-page .grid .card h3{color:#ffffff!important}.shop-page .grid .card .price{color:#a78bfa!important}.shop-page .grid .card .old,.shop-page .grid .card .stars small{color:#cbd5e1!important}
.shop-page .grid .card .cta{background:linear-gradient(180deg,#22d3ee,#a78bfa)!important;color:#0b1020!important;border:0;border-radius:14px!important;font-weight:900;box-shadow:none}.shop-page .grid .card:hover{transform:translateY(-4px)}.shop-page .grid .card:hover .cta{filter:brightness(1.08)}
